import type { Session } from "@kurasu/contract/sessions";
import type { Position } from "@kurasu/slides/messages";
import { useQueryClient } from "@tanstack/react-query";
import { useRef, useState } from "react";

import { queryKeys } from "../../api/query-keys.ts";
import { useAdminMaterials } from "../materials/useAdminMaterials.ts";
import { useSlidesMaterial } from "../materials/useSlidesMaterial.ts";
import { useMoveSlide } from "../sessions/useMoveSlide.ts";
import { PresentButton } from "./PresentButton.tsx";
import { SlideStage } from "./SlideStage.tsx";
import { SlideStageSkeleton } from "./SlideStageSkeleton.tsx";

interface Props {
  session: Session;
}

const isSame = (a: Position, b: Position) => a.slide === b.slide && a.step === b.step;

// The teacher drives the session's position. While moves save, the screen
// shows its own position and ignores what the server answers, because those
// answers arrive late and would send it back. Moves save one at a time, and a
// move made while another saves only keeps the last position.
export const TeacherSlides = ({ session }: Props) => {
  const queryClient = useQueryClient();
  const materials = useAdminMaterials(session.id);
  const slides = useSlidesMaterial(materials.data);
  const move = useMoveSlide();

  const [moving, setMoving] = useState<Position | null>(null);
  const isSaving = useRef(false);
  const waiting = useRef<Position | null>(null);

  const save = (position: Position) => {
    isSaving.current = true;

    move
      .mutateAsync({ id: session.id, position })
      .then(async (saved) => {
        const next = waiting.current;

        waiting.current = null;

        if (next != null && !isSame(next, position)) {
          save(next);

          return;
        }

        await queryClient.cancelQueries({
          queryKey: queryKeys.adminSession(session.id),
          exact: true,
        });
        queryClient.setQueryData(queryKeys.adminSession(session.id), saved);
        isSaving.current = false;
        setMoving(null);
      })
      .catch(() => {
        waiting.current = null;
        isSaving.current = false;
        setMoving(null);
      });
  };

  const navigate = (position: Position) => {
    setMoving(position);

    if (isSaving.current) {
      waiting.current = position;

      return;
    }

    save(position);
  };

  const position = moving ?? { slide: session.currentSlide, step: session.currentStep };
  const controls = <PresentButton sessionId={session.id} />;

  return materials.data == null || (slides != null && slides.html == null) ? (
    <SlideStageSkeleton controls={controls} />
  ) : (
    <SlideStage
      html={slides?.html ?? null}
      position={position}
      onNavigate={navigate}
      controls={controls}
    />
  );
};
